    73	pub fn validate(index: &Index, tasks: &Tasks, root: &Path) -> Result<(), String> {
    74	    if index.unit != "estimated-bytes-v1" || !index.budget.checked_add(0).is_some() {
    75	        return Err("invalid metadata unit or budget".into());
    76	    }
    77	    let ids: Vec<_> = index.documents.iter().map(|d| d.id.as_str()).collect();
    78	    if unique(&ids) == false {
    79	        return Err("duplicate document id".into());
    80	    }
    81	    let orders: Vec<_> = index.documents.iter().map(|d| d.order).collect();
    82	    if unique(&orders) == false {
    83	        return Err("duplicate document order".into());
    84	    }
    85	    for d in &index.documents {
    86	        if d.path.is_empty()
    87	            || Path::new(&d.path).is_absolute()
    88	            || d.path.split('/').any(|p| p == "..")
    89	        {
    90	            return Err(format!("invalid path for {}", d.id));
    91	        }
    92	        if !root.join(&d.path).starts_with(root) {
    93	            return Err(format!("path escapes root: {}", d.path));
    94	        }
    95	    }
    96	    let task_ids: Vec<_> = tasks.tasks.iter().map(|t| t.id.as_str()).collect();
    97	    if !unique(&task_ids) {
    98	        return Err("duplicate task id".into());
    99	    }
   100	    Ok(())
   101	}
   102	fn unique<T: Eq + std::hash::Hash>(v: &[T]) -> bool {
   103	    let mut s = std::collections::HashSet::new();
   104	    v.iter().all(|x| s.insert(x))
   105	}
   106	fn words(s: &str) -> Vec<String> {
   107	    s.split(|c: char| !c.is_alphanumeric())
   108	        .filter(|x| x.len() > 1)
   109	        .map(|x| x.to_lowercase())
   110	        .collect()
   111	}
   112	fn select(index: &Index, task: &Task, strategy: &str) -> Vec<Document> {
   113	    let q = words(&task.question);
   114	    let mut docs = index.documents.clone();
   115	    match strategy {
   116	        "on-demand" => docs.retain(|d| {
   117	            d.keywords.iter().any(|k| task.question.contains(k)) || task.question.contains(&d.title)
