   111	fn choose(t: &Task, ds: &[Document], k: &str) -> Vec<usize> {
   112	    let q = words(&t.question);
   113	    let mut a: Vec<(usize, i32)> =
   114	        ds.iter()
   115	            .enumerate()
   116	            .map(|(i, d)| {
   117	                (
   118	                    i,
   119	                    q.iter()
   120	                        .map(|w| {
   121	                            d.keywords.iter().any(|x| {
   122	                                x.to_lowercase().contains(w) || w.contains(&x.to_lowercase())
   123	                            }) as i32
   124	                        })
   125	                        .sum(),
   126	                )
   127	            })
   128	            .collect();
   129	    match k {
   130	        "on-demand" => {
   131	            a.retain(|x| x.1 > 0);
   132	            a.sort_by_key(|x| ds[x.0].order)
   133	        }
   134	        "retrieval" => {
   135	            a.sort_by(|x, y| y.1.cmp(&x.1).then(ds[x.0].order.cmp(&ds[y.0].order)));
   136	            a.retain(|x| x.1 > 0);
   137	            a.truncate(3)
   138	        }
   139	        _ => a.sort_by_key(|x| ds[x.0].order),
   140	    }
   141	    a.into_iter().map(|x| x.0).collect()
   142	}
