   154	fn answer(q: &str, ms: &[Message]) -> Answer {
   155	    let mut all = Vec::new();
   156	    for m in ms {
   157	        if let Some((h, b)) = m.content.split_once('\n') {
   158	            if let Some(s) = h.strip_prefix("[来源:").and_then(|x| x.strip_suffix(']')) {
   159	                all.extend(facts(b, s))
   160	            }
   161	        }
   162	    }
   163	    let fs = ["传输方式", "协议版本", "检查命令", "批准状态", "处理动作"];
   164	    let c = fs
   165	        .iter()
   166	        .filter(|f| q.contains(**f) || (**f == "处理动作" && q.contains("动作")))
   167	        .filter_map(|f| all.iter().find(|x| x.field == **f).cloned())
   168	        .collect::<Vec<_>>();
   169	    Answer {
   170	        raw_answer: c
   171	            .iter()
   172	            .map(|x| format!("{}：{}（来源：{}）", x.field, x.value, x.source))
   173	            .collect::<Vec<_>>()
   174	            .join("\n"),
   175	        insufficient_evidence: c.is_empty(),
   176	        claims: c,
   177	    }
   178	}
