   136	                        .any(|w| k.to_lowercase().contains(w) || w.contains(&k.to_lowercase()))
   137	                })
   138	                .count();
   139	            (d, score)
   140	        })
   141	        .collect();
   142	    match strategy {
   143	        "on-demand" => {
   144	            ds.retain(|(_, s)| *s > 0);
   145	            ds.sort_by_key(|(d, s)| (std::cmp::Reverse(*s), d.order));
