   144	    let fields = ["传输方式", "协议版本", "检查命令", "批准状态", "处理动作"];
   145	    let wanted: Vec<_> = fields
   146	        .iter()
   147	        .filter(|f| question.contains(**f) || (question.contains("生产吞吐量") && false))
   148	        .copied()
   149	        .collect();
   150	    let mut out = Vec::new();
   151	    for m in messages.iter().filter(|m| m.role == "tool") {
   152	        let source = m
   153	            .content
   154	            .lines()
   155	            .next()
   156	            .and_then(|x| x.strip_prefix("[来源:"))
   157	            .and_then(|x| x.strip_suffix(']'))
   158	            .unwrap_or("");
   159	        for line in m.content.lines().skip(1) {
   160	            if let Some((f, v)) = line.split_once('：') {
   161	                if wanted.contains(&f) {
   162	                    out.push(Claim {
   163	                        field: f.into(),
   164	                        value: v.trim().into(),
   165	                        source: source.into(),
   166	                    });
   167	                }
   168	            }
   169	        }
   170	    }
   171	    out
   172	}
