   132	                .keywords
   133	                .iter()
   134	                .filter(|k| {
   135	                    q.iter()
   136	                        .any(|w| k.to_lowercase().contains(w) || w.contains(&k.to_lowercase()))
   137	                })
   138	                .count();
   139	            (d, score)
   140	        })
   141	        .collect();
   142	    match strategy {
   143	        "on-demand" => {
   144	            ds.retain(|(_, s)| *s > 0);
   145	            ds.sort_by_key(|(d, s)| (std::cmp::Reverse(*s), d.order));
   146	        }
   147	        "retrieval" => {
   148	            ds.retain(|(_, s)| *s > 0);
   149	            ds.sort_by_key(|(d, s)| (std::cmp::Reverse(*s), d.order));
   150	        }
