   171	fn extract(messages: &[Message], question: &str) -> Answer {
   172	    let fields: Vec<(&str, &[&str])> = vec![
   173	        ("传输方式", &["传输方式", "传输"]),
   174	        ("协议版本", &["协议版本", "协议"]),
   175	        ("检查命令", &["检查命令"]),
   176	        ("批准状态", &["批准状态"]),
   177	        ("处理动作", &["处理动作"]),
   178	        ("生产吞吐量", &["吞吐量"]),
   179	    ];
