   181	    for (field, aliases) in fields {
   182	        if !aliases.iter().any(|a| question.contains(a)) {
   183	            continue;
   184	        }
   185	        for m in messages {
   186	            if !m.content.starts_with("[来源:") {
   187	                continue;
